101	\begin{lemma}\label{lem:alnf}
102		\lean{MIPStarRE.QPBT.aLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.aLinePointDist_mem_line}
103		\leanok
104		\uses{def:ld-question-distribution, def:line}
105		Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,0),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, e_i)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a line that goes through $u$ and is parallel to a uniformly random axis $i \in \{1,2,\ldots,m\}$.
106	\end{lemma}
107	\begin{proof}
108		\leanok
109		\uses{def:cl-dist, def:ld-question-distribution, def:line-representative, lem:line-rep-incidence}
