1379	\begin{definition}[Graph distribution]\label{def:graph-distribution}
1380		\lean{MIPStarRE.QPBT.graphDistribution}
1381		\leanok
1382		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
1383		\[
1384			\mu_G(u, v) =
1385			\begin{cases}
1386				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
1387				0 & \text{otherwise}\,.
1388			\end{cases}
1389		\]
1390		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
1391	\end{definition}
1392	
1393	\begin{lemma}[Formalization support for normalization of the graph distribution]\label{lem:graph-distribution-mass}
1394		\lean{MIPStarRE.QPBT.graphDistribution_isProbability}
1395		\leanok
1396		\uses{def:graph-distribution}
1397		This is not a named statement of the source article; it records the normalization of the graph distribution of Definition~\ref{def:graph-distribution}, which the source leaves implicit. Let $G = (U, E)$ be an undirected graph with nonempty edge set $E$. Then the graph distribution $\mu_G$ has total mass one, that is, $\sum_{(u,v) \in U \times U} \mu_G(u,v) = 1$.
1398	\end{lemma}
1399	\begin{proof}
1400		\leanok
1401		\uses{def:graph-distribution}
1402		The distribution $\mu_G$ is uniform on the set of ordered pairs $(u,v) \in U \times U$ with $\{u,v\} \in E$, and that set is nonempty because $E$ is: an edge $\{u,v\} \in E$ yields the ordered pair $(u,v)$. A uniform distribution on a nonempty finite set has total mass one.
1403	\end{proof}
