1410	% definition imposes on L and R, so it is a strict generalization of the definition below and
1411	% the node is left unmarked, exactly as for def:cl-dist. The identifications of the two
1412	% concrete samplers with this construction are stated separately as lem:ld-question-typed-cl
1413	% and lem:pauli-question-typed-cl in Chapter chap:qpbt-test.
1414	\begin{definition}[Typed conditionally linear distributions]\label{def:typed-cl-distributions}
1415		\lean{MIPStarRE.QPBT.typedCLDistribution}
1416		\uses{def:typed-cl-functions, def:graph-distribution, def:cl-dist}
1417		Let $\mathcal T$ be a type set and let $L = \{L_u\}_{u \in \mathcal T}$ and $R = \{R_v\}_{v \in \mathcal T}$ be $\mathcal T$-typed families of conditionally linear functions on $V$. Let $G = (\mathcal T, E)$ be a graph with vertex set $\mathcal T$ and nonempty edge set $E$, so that the graph distribution $\mu_G$ of Definition~\ref{def:graph-distribution} is defined. The \emph{$(\mathcal T, G)$-typed conditionally linear distribution $\mu^G_{L,\,R}$ corresponding to $(L, R)$} is the distribution over pairs $\bigl( (u, x), (v, y) \bigr)$, where the type pair $(u,v)$ is drawn from the graph distribution $\mu_G$ and the content pair $(x,y)$ is drawn from $\mu_{L_u,\,R_v}$.
1418	\end{definition}

